12	export function findGroupByPath(group: FilterGroup, path: number[]): FilterGroup | null {
13	  if (path.length === 0) return group
14	
15	  const [current, ...rest] = path
16	  const condition = group.conditions[current]
17	  if (!condition) return null
18	
19	  if (rest.length === 0) {
20	    return isGroup(condition) ? condition : null
21	  }
22	
23	  if (isGroup(condition)) {
24	    return findGroupByPath(condition, rest)
25	  }
26	
27	  return null
28	}
29	
30	export function findConditionByPath(group: FilterGroup, path: number[]): FilterCondition | null {
31	  if (path.length === 0) return null
32	
33	  const [current, ...rest] = path
34	  const condition = group.conditions[current]
35	  if (!condition) return null
36	
37	  if (rest.length === 0) {
38	    return isGroup(condition) ? null : condition
39	  }
40	
41	  if (isGroup(condition)) {
42	    return findConditionByPath(condition, rest)
43	  }
44	
45	  return null
46	}
47	
48	export function isCustomOptionObject(option: any): option is CustomOptionObject {
49	  return typeof option === 'object' && option !== null && 'component' in option
50	}
51	
52	export function isFilterOptionObject(option: any): option is FilterOptionObject {
53	  return typeof option === 'object' && option !== null && 'value' in option && 'label' in option
54	}
55	
56	export function isAsyncOptionsFunction(
57	  options: FilterProperty['options']
58	): options is AsyncOptionsFunction {
59	  if (!options || Array.isArray(options) || isCustomOptionObject(options)) return false
60	  if (typeof options !== 'function') return false
61	  // More reliable async function detection
62	  const fnString = options.toString()
63	  return options.constructor.name === 'AsyncFunction' ||
64	         fnString.startsWith('async ') ||
65	         fnString.includes('async function')
66	}
67	
68	export function isSyncOptionsFunction(options: FilterProperty['options']): options is SyncOptionsFunction {
69	  if (!options || Array.isArray(options) || isCustomOptionObject(options)) return false
70	  return typeof options === 'function'
71	}
72	
73	export function updateNestedFilter(
74	  group: FilterGroup,
75	  path: number[],
76	  updateFn: (condition: FilterCondition) => FilterCondition
77	): FilterGroup {
78	  if (path.length === 1) {
79	    return {
